function esc(v) {
    return String(v == null ? "" : v).replace(/'/g, "''");
}

function isRows(v) {
    return Object.prototype.toString.call(v) === "[object Array]";
}

function logMsg(eventtype, source, message, sid) {
    return {
        sp: { flow: "log" },
        topic:
            "INSERT INTO event_logs(eventtype,source,message,parking_session_id) VALUES('" +
            esc(eventtype) + "','" +
            esc(source || "node-red") + "','" +
            esc(message || "") + "'," +
            (sid == null ? "NULL" : Number(sid)) +
            ");"
    };
}

function mqttPayload(o) {
    return o;
}

function sqliteUtcDate(value) {
    var text = String(value || "");

    if (text.indexOf("T") < 0) {
        text = text.replace(" ", "T");
    }

    if (text.charAt(text.length - 1) !== "Z") {
        text = text + "Z";
    }

    return new Date(text);
}

function price(entry) {
    var started = sqliteUtcDate(entry);
    var now = new Date();
    var diffMs = now.getTime() - started.getTime();

    if (isNaN(diffMs) || diffMs < 0) {
        diffMs = 0;
    }

    var mins = Math.max(1, Math.ceil(diffMs / 60000));
    var due = Math.max(1, Math.ceil(mins / 15) * 0.5);

    return {
        minutes: mins,
        amount_due: Number(due.toFixed(2))
    };
}

function nextSp(oldSp, flowName) {
    var s = {};
    var k;

    for (k in oldSp) {
        if (oldSp.hasOwnProperty(k)) {
            s[k] = oldSp[k];
        }
    }

    s.flow = flowName;
    return s;
}

function handleApi(rows, sp) {
    if (sp.flow === "health") {
        msg.statusCode = 200;
        msg.payload = {
            status: "ok",
            database: "reachable"
        };
        return [null, msg, null, null, null, null];
    }

    if (sp.flow === "list") {
        msg.statusCode = 200;
        return [null, msg, null, null, null, null];
    }

    if (sp.flow === "session_current") {
        if (rows.length < 1) {
            msg.statusCode = 404;
            msg.payload = {
                error: "no_active_session",
                plate: sp.plate
            };
            return [null, msg, null, null, null, null];
        }

        var session = rows[0];
        var currentPrice = price(session.entry_time);

        msg.statusCode = 200;
        msg.payload = {
            session_id: session.id,
            plate: session.plate,
            entry_time: session.entry_time,
            payment_time: session.payment_time,
            exit_valid_until: session.exit_valid_until,
            amount_paid: Number(session.amount_paid || 0),
            minutes: currentPrice.minutes,
            amount_due: currentPrice.amount_due
        };

        return [null, msg, null, null, null, null];
    }

    return null;
}

function handlePayment(rows, sp) {
    if (sp.flow === "payment_check") {
        if (rows.length < 1) {
            msg.statusCode = 404;
            msg.payload = {
                error: "no_active_session",
                plate: sp.plate
            };

            return [
                [logMsg("PAYMENT_FAILED", "payment-api", "Payment failed: no active session for " + sp.plate, null)],
                msg,
                null,
                null,
                null,
                null
            ];
        }

        var paySession = rows[0];
        var payPrice = price(paySession.entry_time);

        if (Number(sp.amount_paid) < payPrice.amount_due) {
            msg.statusCode = 402;
            msg.payload = {
                status: "failed",
                error: "amount_too_low",
                plate: paySession.plate,
                amount_due: payPrice.amount_due,
                amount_paid: Number(sp.amount_paid)
            };

            return [
                [logMsg("PAYMENT_FAILED", "payment-api", "Payment failed for " + paySession.plate + ": amount too low", paySession.id)],
                msg,
                null,
                null,
                null,
                null
            ];
        }

        msg.sp = {
            flow: "payment_done",
            plate: sp.plate,
            session_id: paySession.id,
            amount_paid: Number(sp.amount_paid),
            amount_due: payPrice.amount_due,
            minutes: payPrice.minutes
        };

        msg.topic =
            "UPDATE parking_sessions SET " +
            "payment_time=CURRENT_TIMESTAMP," +
            "amount_due=" + payPrice.amount_due + "," +
            "amount_paid=" + Number(sp.amount_paid) + "," +
            "exit_valid_until=datetime('now','+15 minutes') " +
            "WHERE id=" + Number(paySession.id) + ";";

        return [msg, null, null, null, null, null];
    }

    if (sp.flow === "payment_done") {
        msg.statusCode = 200;
        msg.payload = {
            status: "paid",
            plate: sp.plate,
            session_id: sp.session_id,
            minutes: sp.minutes,
            amount_due: sp.amount_due,
            amount_paid: sp.amount_paid,
            exit_valid_minutes: 15
        };

        return [
            [logMsg("PAYMENT_SUCCESS", "payment-api", "Payment successful for " + sp.plate, sp.session_id)],
            msg,
            null,
            null,
            null,
            null
        ];
    }

    return null;
}

function handleEntry(rows, sp) {
    if (sp.flow === "entry_check") {
        if (rows.length > 0) {
            var activeEntry = rows[0];

            return [
                [logMsg("ENTRY_PLATE_DETECTED", sp.source, "Duplicate entry ignored for active plate " + sp.plate, activeEntry.id)],
                null,
                null,
                {
                    payload: mqttPayload({
                        text: "Bereits aktiv: " + sp.plate,
                        plate: sp.plate
                    })
                },
                null,
                null
            ];
        }

        msg.sp = nextSp(sp, "entry_insert");
        msg.topic =
            "INSERT INTO parking_sessions(plate,amount_due,amount_paid) VALUES('" +
            esc(sp.plate) +
            "',0,0);";

        return [msg, null, null, null, null, null];
    }

    if (sp.flow === "entry_insert") {
        msg.sp = nextSp(sp, "entry_select");
        msg.topic =
            "SELECT * FROM parking_sessions WHERE plate='" +
            esc(sp.plate) +
            "' AND exit_time IS NULL ORDER BY id DESC LIMIT 1;";

        return [msg, null, null, null, null, null];
    }

    if (sp.flow === "entry_select") {
        var createdEntry = rows.length > 0 ? rows[0] : {};
        var entrySessionId = createdEntry.id == null ? null : createdEntry.id;

        return [
            [
                logMsg("ENTRY_PLATE_DETECTED", sp.source, "Entry plate detected: " + sp.plate, entrySessionId),
                logMsg("ENTRY_BARRIER_OPENED", "node-red", "Entry barrier opened for " + sp.plate, entrySessionId)
            ],
            null,
            {
                payload: mqttPayload({
                    command: "OPEN",
                    plate: sp.plate
                })
            },
            {
                payload: mqttPayload({
                    text: "Willkommen " + sp.plate,
                    plate: sp.plate
                })
            },
            null,
            null
        ];
    }

    return null;
}

function handleExit(rows, sp) {
    if (sp.flow === "exit_check") {
        if (rows.length < 1) {
            return [
                [logMsg("EXIT_PLATE_DETECTED", sp.source, "Exit denied: no active session for " + sp.plate, null)],
                null,
                null,
                null,
                null,
                {
                    payload: mqttPayload({
                        text: "Keine aktive Session",
                        plate: sp.plate
                    })
                }
            ];
        }

        var exitSession = rows[0];
        var paid =
            Number(exitSession.amount_paid || 0) >= Number(exitSession.amount_due || 0) &&
            Number(exitSession.amount_due || 0) > 0;

        var validUntil = null;
        var valid = false;

        if (exitSession.exit_valid_until) {
            validUntil = new Date(String(exitSession.exit_valid_until).replace(" ", "T") + "Z");
            valid = paid && validUntil.getTime() >= new Date().getTime();
        }

        var detectLog = logMsg(
            "EXIT_PLATE_DETECTED",
            sp.source,
            "Exit plate detected: " + sp.plate,
            exitSession.id
        );

        if (!valid) {
            return [
                [detectLog],
                null,
                null,
                null,
                null,
                {
                    payload: mqttPayload({
                        text: paid ? "Zeitfenster abgelaufen" : "Bitte bezahlen",
                        plate: sp.plate,
                        amount_due: Number(exitSession.amount_due || 0),
                        amount_paid: Number(exitSession.amount_paid || 0)
                    })
                }
            ];
        }

        msg.sp = nextSp(sp, "exit_done");
        msg.sp.session_id = exitSession.id;
        msg.topic =
            "UPDATE parking_sessions SET exit_time=CURRENT_TIMESTAMP WHERE id=" +
            Number(exitSession.id) +
            ";";

        return [[detectLog, msg], null, null, null, null, null];
    }

    if (sp.flow === "exit_done") {
        return [
            [logMsg("EXIT_BARRIER_OPENED", "node-red", "Exit barrier opened for " + sp.plate, sp.session_id)],
            null,
            null,
            null,
            {
                payload: mqttPayload({
                    command: "OPEN",
                    plate: sp.plate
                })
            },
            {
                payload: mqttPayload({
                    text: "Gute Fahrt " + sp.plate,
                    plate: sp.plate
                })
            }
        ];
    }

    return null;
}

function handleRfid(rows, sp) {
    if (sp.flow === "rfid_admin") {
        if (rows.length < 1) {
            return [
                [logMsg("RFID_ADMIN_RELEASE", sp.source, "RFID denied for uid " + sp.rfid_uid, null)],
                null,
                null,
                null,
                null,
                {
                    payload: mqttPayload({
                        text: "RFID nicht berechtigt",
                        plate: sp.plate
                    })
                }
            ];
        }

        msg.sp = nextSp(sp, "rfid_session");
        msg.sp.admin = rows[0];

        msg.topic =
            "SELECT * FROM parking_sessions WHERE plate='" +
            esc(sp.plate) +
            "' AND exit_time IS NULL ORDER BY id DESC LIMIT 1;";

        return [msg, null, null, null, null, null];
    }

    if (sp.flow === "rfid_session") {
        if (rows.length < 1) {
            return [
                [logMsg("RFID_ADMIN_RELEASE", sp.source, "RFID release denied: no active session for " + sp.plate, null)],
                null,
                null,
                null,
                null,
                {
                    payload: mqttPayload({
                        text: "Keine aktive Session",
                        plate: sp.plate
                    })
                }
            ];
        }

        var rfidSession = rows[0];

        msg.sp = nextSp(sp, "rfid_insert");
        msg.sp.session_id = rfidSession.id;

        msg.topic =
            "INSERT INTO rfid_admin_releases(admin_id,rfid_uid,parking_session_id) VALUES(" +
            Number(sp.admin.id) +
            ",'" +
            esc(sp.rfid_uid) +
            "'," +
            Number(rfidSession.id) +
            ");";

        return [msg, null, null, null, null, null];
    }

    if (sp.flow === "rfid_insert") {
        msg.sp = nextSp(sp, "rfid_done");
        msg.topic =
            "UPDATE parking_sessions SET exit_time=CURRENT_TIMESTAMP WHERE id=" +
            Number(sp.session_id) +
            ";";

        return [msg, null, null, null, null, null];
    }

    if (sp.flow === "rfid_done") {
        return [
            [logMsg("RFID_ADMIN_RELEASE", sp.source, "RFID admin release by " + sp.admin.name + " for " + sp.plate, sp.session_id)],
            null,
            null,
            null,
            {
                payload: mqttPayload({
                    command: "OPEN",
                    plate: sp.plate,
                    reason: "RFID_ADMIN_RELEASE"
                })
            },
            {
                payload: mqttPayload({
                    text: "Admin-Freigabe",
                    plate: sp.plate
                })
            }
        ];
    }

    return null;
}

var rows = isRows(msg.payload) ? msg.payload : [];
var sp = msg.sp || {};
var result = null;

if (sp.flow === "log") {
    return null;
}

result = handleApi(rows, sp);
if (result) {
    return result;
}

result = handlePayment(rows, sp);
if (result) {
    return result;
}

result = handleEntry(rows, sp);
if (result) {
